(7136468, 1093584, 37858, '<td valign="top">I wish this wasn''t quite so dark as details are a bit hard to distill from this image.  I like the composition, though.</td>', 'I wish this wasn''t quite so dark as details are a bit hard to distill from this image.  I like the composition, though.', '2013-11-30 01:42:58.000000', NULL, 1),
(7136469, 1093564, 37858, '<td valign="top">I don''t know why I like this, but I do.</td>', 'I don''t know why I like this, but I do.', '2013-11-30 01:43:58.000000', NULL, 1),
(7136470, 1093537, 37858, '<td valign="top">I think you were on to something here, but the drastic tilt seems gratuitous to me.  It doesn''t seem to be tied into any meaning or any action within the photo, so I am left wondering why the world suddenly tilted about 45 degrees.  (Of course, I am also willing to accept that I simply missed the point.)</td>', 'I think you were on to something here, but the drastic tilt seems gratuitous to me.  It doesn''t seem to be tied into any meaning or any action within the photo, so I am left wondering why the world suddenly tilted about 45 degrees.  (Of course, I am also willing to accept that I simply missed the point.)', '2013-11-30 01:47:42.000000', NULL, 1),
(7136590, 1093542, 118154, '<td valign="top">Not sure about the long exposure but I really enjoy this image.</td>', 'Not sure about the long exposure but I really enjoy this image.', '2013-11-30 12:34:45.000000', NULL, 1),
(7136722, 1093561, 119419, '<td valign="top">Lovely to sit and ponder this, absorbing the subtle xrayness. It''s rewarding to see the other figures emerge to complete the scene, the benefit of taking the time I suppose.</td>', 'Lovely to sit and ponder this, absorbing the subtle xrayness. It''s rewarding to see the other figures emerge to complete the scene, the benefit of taking the time I suppose.', '2013-11-30 23:21:48.000000', NULL, 1),
(7136724, 1093514, 119419, '<td valign="top">LE always brings out the most subtle aspects, especially in mono. A wonderful piece that also serves to remind one how much the sensor hides in normal shooting. Nice leading lines.</td>', 'LE always brings out the most subtle aspects, especially in mono. A wonderful piece that also serves to remind one how much the sensor hides in normal shooting. Nice leading lines.', '2013-11-30 23:24:40.000000', NULL, 1),
(7136726, 1093589, 119419, '<td valign="top">a nice composition, has a wonderful tranquility.</td>', 'a nice composition, has a wonderful tranquility.', '2013-11-30 23:29:42.000000', NULL, 1),
